package httpapi
import("encoding/json";"errors";"net/http";"strconv";"strings";"time";"github.com/Loccao102/LocCaoEnglish/backend/internal/ai";"github.com/Loccao102/LocCaoEnglish/backend/internal/auth";"github.com/Loccao102/LocCaoEnglish/backend/internal/engine";"github.com/Loccao102/LocCaoEnglish/backend/internal/model";"github.com/Loccao102/LocCaoEnglish/backend/internal/realtime";"github.com/Loccao102/LocCaoEnglish/backend/internal/store")
type Server struct{store *store.Store;auth *auth.Service;ai *ai.Client;social *realtime.Service};func New(st *store.Store,a *auth.Service,aiClient *ai.Client,social *realtime.Service)*Server{return &Server{store:st,auth:a,ai:aiClient,social:social}}
func(s *Server)Handler()http.Handler{mux:=http.NewServeMux();mux.HandleFunc("GET /health",s.health);mux.HandleFunc("POST /v1/auth/register",s.register);mux.HandleFunc("POST /v1/auth/login",s.login);mux.HandleFunc("GET /v1/me",s.me);mux.HandleFunc("GET /v1/dashboard",s.dashboard);mux.HandleFunc("GET /v1/skills",s.skills);mux.HandleFunc("GET /v1/plan/today",s.plan);mux.HandleFunc("POST /v1/attempts",s.attempt);mux.HandleFunc("GET /v1/review",s.reviewQueue);mux.HandleFunc("POST /v1/review/{itemKey}",s.reviewGrade);mux.HandleFunc("GET /v1/lessons",s.lessons);mux.HandleFunc("GET /v1/lessons/{slug}",s.lesson);mux.HandleFunc("POST /v1/lessons/{slug}/complete",s.lessonComplete);mux.HandleFunc("GET /v1/admin/lessons",s.adminLessons);mux.HandleFunc("POST /v1/admin/lessons",s.adminSaveLesson);mux.HandleFunc("DELETE /v1/admin/lessons/{slug}",s.adminDeleteLesson);mux.HandleFunc("GET /v1/social/leaderboard",s.leaderboard);mux.HandleFunc("POST /v1/social/presence",s.presence);mux.HandleFunc("GET /v1/social/online",s.online);mux.HandleFunc("GET /v1/social/challenges",s.challenges);mux.HandleFunc("POST /v1/social/challenges",s.createChallenge);mux.HandleFunc("POST /v1/social/challenges/{id}/submit",s.submitChallenge);mux.HandleFunc("POST /v1/ai/writing-score",s.aiProxy("/v1/writing/score"));mux.HandleFunc("POST /v1/ai/speaking-feedback",s.aiProxy("/v1/speaking/feedback"));mux.HandleFunc("POST /v1/ai/pronunciation-score",s.aiProxyWithLimit("/v1/pronunciation/score",8<<20));mux.HandleFunc("POST /v1/ai/tts",s.aiProxy("/v1/tts/synthesize"));mux.HandleFunc("POST /v1/ai/exercises",s.aiProxy("/v1/exercises/generate"));mux.HandleFunc("POST /v1/conversation/reply",s.aiProxy("/v1/conversation/reply"));mux.HandleFunc("GET /v1/missions/airport",s.airportMission);return s.cors(mux)}
func(s *Server)health(w http.ResponseWriter,r *http.Request){write(w,200,map[string]any{"status":"ok","store":s.store.Mode(),"realtime":s.social.Mode(),"time":time.Now().UTC()})}
func(s *Server)register(w http.ResponseWriter,r *http.Request){var in struct{Email,Password,DisplayName string};if!decode(w,r,&in){return};hash,err:=auth.HashPassword(in.Password);if err!=nil{problem(w,400,err.Error());return};u,err:=s.store.CreateUser(r.Context(),in.Email,hash,in.DisplayName);if errors.Is(err,store.ErrEmailExists){problem(w,409,err.Error());return};if err!=nil{problem(w,500,err.Error());return};token,_:=s.auth.Issue(u.ID);write(w,201,map[string]any{"user":u,"token":token})}
func(s *Server)login(w http.ResponseWriter,r *http.Request){var in struct{Email,Password string};if!decode(w,r,&in){return};u,hash,err:=s.store.FindUserByEmail(r.Context(),in.Email);if err!=nil||hash==""||!auth.VerifyPassword(hash,in.Password){problem(w,401,"invalid email or password");return};token,_:=s.auth.Issue(u.ID);write(w,200,map[string]any{"user":u,"token":token})}
func(s *Server)me(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};u,err:=s.store.GetUser(r.Context(),id);if err!=nil{problem(w,404,"user not found");return};role,err:=s.store.RoleForUser(r.Context(),id);if err!=nil{problem(w,500,err.Error());return};write(w,200,map[string]any{"user":u,"role":role})}
func(s *Server)dashboard(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};d,err:=s.store.Dashboard(r.Context(),id);if err!=nil{problem(w,500,err.Error());return};write(w,200,d)};func(s *Server)skills(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};items,err:=s.store.Skills(r.Context(),id);if err!=nil{problem(w,500,err.Error());return};write(w,200,map[string]any{"skills":items})};func(s *Server)plan(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};skills,err:=s.store.Skills(r.Context(),id);if err!=nil{problem(w,500,err.Error());return};reviews,_:=s.store.ReviewQueue(r.Context(),id,20);write(w,200,engine.BuildPlan(skills,reviews))};func(s *Server)attempt(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};var in model.AttemptInput;if!decode(w,r,&in){return};if strings.TrimSpace(in.Skill)==""||strings.TrimSpace(in.ItemKey)==""{problem(w,400,"skill and itemKey are required");return};res,err:=s.store.RecordAttempt(r.Context(),id,in);if err!=nil{problem(w,500,err.Error());return};write(w,201,res)};func(s *Server)reviewQueue(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};limit,_:=strconv.Atoi(r.URL.Query().Get("limit"));items,err:=s.store.ReviewQueue(r.Context(),id,limit);if err!=nil{problem(w,500,err.Error());return};write(w,200,map[string]any{"items":items})};func(s *Server)reviewGrade(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};var in struct{Quality int `json:"quality"`};if!decode(w,r,&in){return};if err:=s.store.GradeReview(r.Context(),id,r.PathValue("itemKey"),in.Quality);errors.Is(err,store.ErrNotFound){problem(w,404,"review item not found");return}else if err!=nil{problem(w,500,err.Error());return};write(w,200,map[string]any{"ok":true})}
func(s *Server)lessons(w http.ResponseWriter,r *http.Request){items,err:=s.store.ListLessons(r.Context(),false);if err!=nil{problem(w,500,err.Error());return};write(w,200,map[string]any{"items":items})};func(s *Server)lesson(w http.ResponseWriter,r *http.Request){item,err:=s.store.GetLesson(r.Context(),r.PathValue("slug"),false);if errors.Is(err,store.ErrNotFound){problem(w,404,"lesson not found");return};if err!=nil{problem(w,500,err.Error());return};write(w,200,item)};func(s *Server)lessonComplete(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};lesson,err:=s.store.GetLesson(r.Context(),r.PathValue("slug"),false);if err!=nil{problem(w,404,"lesson not found");return};var in struct{Completed int `json:"completed"`;Score float64 `json:"score"`};if!decode(w,r,&in){return};p,err:=s.store.SaveLessonProgress(r.Context(),id,lesson.ID,in.Completed,len(lesson.Exercises),in.Score);if err!=nil{problem(w,500,err.Error());return};write(w,200,p)};func(s *Server)adminLessons(w http.ResponseWriter,r *http.Request){if _,ok:=s.requireRole(w,r,"teacher","admin");!ok{return};items,err:=s.store.ListLessons(r.Context(),true);if err!=nil{problem(w,500,err.Error());return};write(w,200,map[string]any{"items":items})};func(s *Server)adminSaveLesson(w http.ResponseWriter,r *http.Request){u,ok:=s.requireRole(w,r,"teacher","admin");if!ok{return};var lesson model.Lesson;if!decode(w,r,&lesson){return};saved,err:=s.store.SaveLesson(r.Context(),lesson,u.ID);if err!=nil{problem(w,400,err.Error());return};write(w,200,saved)};func(s *Server)adminDeleteLesson(w http.ResponseWriter,r *http.Request){if _,ok:=s.requireRole(w,r,"teacher","admin");!ok{return};if err:=s.store.DeleteLesson(r.Context(),r.PathValue("slug"));errors.Is(err,store.ErrNotFound){problem(w,404,"lesson not found");return}else if err!=nil{problem(w,500,err.Error());return};write(w,200,map[string]any{"ok":true})}
func(s *Server)leaderboard(w http.ResponseWriter,r *http.Request){limit,_:=strconv.Atoi(r.URL.Query().Get("limit"));items,err:=s.store.TopUsers(r.Context(),limit);if err!=nil{problem(w,500,err.Error());return};online,_:=s.social.Online(r.Context());set:=map[string]bool{};for _,p:=range online{set[p.UserID]=true};for i:=range items{items[i].Online=set[items[i].UserID]};write(w,200,map[string]any{"items":items,"onlineCount":len(online)})};func(s *Server)presence(w http.ResponseWriter,r *http.Request){id,ok:=s.userID(w,r);if!ok{return};u,err:=s.store.GetUser(r.Context(),id);if err!=nil{problem(w,404,"user not found");return};if err=s.social.Touch(r.Context(),u.ID,u.DisplayName);err!=nil{problem(w,500,err.Error());return};write(w,200,map[string]any{"ok":true})};func(s *Server)online(w http.ResponseWriter,r *http.Request){items,err:=s.social.Online(r.Context());if err!=nil{problem(w,500,err.Error());return};write(w,200,map[string]any{"items":items})};func(s *Server)challenges(w http.ResponseWriter,r *http.Request){items,err:=s.social.ListChallenges(r.Context(),20);if err!=nil{problem(w,500,err.Error());return};write(w,200,map[string]any{"items":items})};func(s *Server)createChallenge(w http.ResponseWriter,r *http.Request){u,ok:=s.signedInUser(w,r);if!ok{return};var in struct{Title,Skill,Activity string};if!decode(w,r,&in){return};ch,err:=s.social.CreateChallenge(r.Context(),u.ID,u.DisplayName,in.Title,in.Skill,in.Activity);if err!=nil{problem(w,500,err.Error());return};write(w,201,ch)};func(s *Server)submitChallenge(w http.ResponseWriter,r *http.Request){u,ok:=s.signedInUser(w,r);if!ok{return};var in struct{Score int `json:"score"`};if!decode(w,r,&in){return};ch,err:=s.social.Submit(r.Context(),r.PathValue("id"),u.ID,u.DisplayName,in.Score);if err!=nil{problem(w,404,err.Error());return};write(w,200,ch)}
func(s *Server)aiProxy(path string)http.HandlerFunc{return s.aiProxyWithLimit(path,1<<20)};func(s *Server)aiProxyWithLimit(path string,limit int64)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){if _,ok:=s.userID(w,r);!ok{return};var input map[string]any;if!decodeLimit(w,r,&input,limit){return};var output map[string]any;if err:=s.ai.Post(r.Context(),path,input,&output);err!=nil{problem(w,503,"AI service is offline; the client can continue with local fallback scoring.");return};write(w,200,output)}};func(s *Server)airportMission(w http.ResponseWriter,r *http.Request){write(w,200,map[string]any{"id":"airport-boss","title":"Airport Boss: Missed Flight","goal":"Rebook your flight by completing four English challenges."})}
func(s *Server)signedInUser(w http.ResponseWriter,r *http.Request)(model.User,bool){header:=strings.TrimSpace(r.Header.Get("Authorization"));if header==""{problem(w,401,"sign in required");return model.User{},false};parts:=strings.SplitN(header," ",2);if len(parts)!=2||!strings.EqualFold(parts[0],"Bearer"){problem(w,401,"invalid authorization header");return model.User{},false};id,err:=s.auth.Parse(parts[1]);if err!=nil{problem(w,401,"invalid or expired token");return model.User{},false};u,err:=s.store.GetUser(r.Context(),id);if err!=nil{problem(w,401,"user not found");return model.User{},false};return u,true};func(s *Server)requireRole(w http.ResponseWriter,r *http.Request,roles ...string)(model.User,bool){u,ok:=s.signedInUser(w,r);if!ok{return model.User{},false};role,err:=s.store.RoleForUser(r.Context(),u.ID);if err!=nil{problem(w,500,err.Error());return model.User{},false};for _,allowed:=range roles{if role==allowed{return u,true}};problem(w,403,"teacher or admin role required");return model.User{},false};func(s *Server)userID(w http.ResponseWriter,r *http.Request)(string,bool){header:=strings.TrimSpace(r.Header.Get("Authorization"));if header==""{return s.store.DemoID(),true};parts:=strings.SplitN(header," ",2);if len(parts)!=2||!strings.EqualFold(parts[0],"Bearer"){problem(w,401,"invalid authorization header");return"",false};id,err:=s.auth.Parse(parts[1]);if err!=nil{problem(w,401,"invalid or expired token");return"",false};return id,true}
func(s *Server)cors(next http.Handler)http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Header().Set("Access-Control-Allow-Origin","*");w.Header().Set("Access-Control-Allow-Headers","Authorization, Content-Type");w.Header().Set("Access-Control-Allow-Methods","GET, POST, PUT, PATCH, DELETE, OPTIONS");if r.Method==http.MethodOptions{w.WriteHeader(204);return};next.ServeHTTP(w,r)})};func decode(w http.ResponseWriter,r *http.Request,out any)bool{return decodeLimit(w,r,out,1<<20)};func decodeLimit(w http.ResponseWriter,r *http.Request,out any,limit int64)bool{dec:=json.NewDecoder(http.MaxBytesReader(w,r.Body,limit));dec.DisallowUnknownFields();if err:=dec.Decode(out);err!=nil{problem(w,400,"invalid JSON: "+err.Error());return false};return true};func write(w http.ResponseWriter,status int,value any){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_=json.NewEncoder(w).Encode(value)};func problem(w http.ResponseWriter,status int,message string){write(w,status,map[string]any{"error":message})}
